def find_minimal_velocity(N, attractiveness):
    left, right = 1, max(attractiveness)

    while left < right:
        mid = (left + right) // 2
        valid = True
        for i in range(N):
            if mid < attractiveness[i]:
                valid = False
                break
            mid -= 1
        if valid:
            right = mid
        else:
            left = mid + 1

    return left

